// Tiny JPEG files for the JPEG header reader and the PDF image tests, checked in as bytes (base64). Each is 2 × 1
// pixels. The RGB and grey files were made with cjpeg (libjpeg-turbo) from a hand-written 2 × 1 PPM/PGM, the CMYK file
// with Pillow; every file decodes in an ordinary image viewer.

const bytes = (base64: string): Uint8Array => Uint8Array.from(Buffer.from(base64, 'base64'));

